# PTX source for a simple FP16 GEMM kernel (row‑major, no tiling)
PTX_SOURCE = r'''
.version 8.0
.target sm_80
.address_size 64

.visible .entry gemm_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // registers
    .reg .u64 a_ptr, b_ptr, c_ptr;
    .reg .u32 m, n, k_dim;
    .reg .u32 tid_x, tid_y;
    .reg .u32 block_x, block_y;
    .reg .u32 blockDim_x, blockDim_y;
    .reg .u32 row, col;
    .reg .pred p_row, p_col, p_oob, p_done;
    .reg .u32 k;
    .reg .u64 addr_a, addr_b, addr_c;
    .reg .f16 a_f16, b_f16, c_f16;
    .reg .f32 a_f32, b_f32, acc;

    // load kernel parameters
    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 m, [M];
    ld.param.u32 n, [N];
    ld.param.u32 k_dim, [K];

    // thread and block indices
    mov.u32 tid_x, %tid.x;
    mov.u32 tid_y, %tid.y;
    mov.u32 block_x, %ctaid.x;
    mov.u32 block_y, %ctaid.y;
    mov.u32 blockDim_x, %ntid.x;
    mov.u32 blockDim_y, %ntid.y;

    // compute global row and column
    mad.lo.u32 row, block_y, blockDim_y, tid_y;   // row = block_y * blockDim_y + tid_y
    mad.lo.u32 col, block_x, blockDim_x, tid_x;   // col = block_x * blockDim_x + tid_x

    // bounds check – exit if out of range
    setp.ge.u32 p_row, row, m;
    setp.ge.u32 p_col, col, n;
    or.pred p_oob, p_row, p_col;
    @p_oob ret;

    // accumulator in fp32
    mov.f32 acc, 0f00000000;

    // k‑loop
    mov.u32 k, 0;
LOOP:
    setp.ge.u32 p_done, k, k_dim;
    @p_done bra END_LOOP;

    // address of A[row, k] (row‑major)
    mul.wide.u32 addr_a, row, k_dim;      // row * K
    add.u32 addr_a, addr_a, k;            // + k
    mul.wide.u32 addr_a, addr_a, 2;       // * sizeof(half)
    add.u64 addr_a, a_ptr, addr_a;
    ld.global.f16 a_f16, [addr_a];

    // address of B[k, col] (row‑major)
    mul.wide.u32 addr_b, k, n;            // k * N
    add.u32 addr_b, addr_b, col;          // + col
    mul.wide.u32 addr_b, addr_b, 2;       // * sizeof(half)
    add.u64 addr_b, b_ptr, addr_b;
    ld.global.f16 b_f16, [addr_b];

    // convert to fp32
    cvt.f32.f16 a_f32, a_f16;
    cvt.f32.f16 b_f32, b_f16;

    // acc += a * b
    fma.rn.f32 acc, a_f32, b_f32, acc;

    // next k
    add.u32 k, k, 1;
    bra LOOP;
END_LOOP:

    // convert result back to fp16 (round‑to‑nearest‑even)
    cvt.rn.f16.f32 c_f16, acc;

    // store C[row, col]
    mul.wide.u32 addr_c, row, n;          // row * N
    add.u32 addr_c, addr_c, col;          // + col
    mul.wide.u32 addr_c, addr_c, 2;       // * sizeof(half)
    add.u64 addr_c, c_ptr, addr_c;
    st.global.f16 [addr_c], c_f16;

    ret;
}
'''

import torch
import torch.nn as nn

# Assume the harness provides these functions
# from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # A: (M, K), B: (K, N), both fp16, contiguous row‑major
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"

        C = torch.empty((M, N), dtype=torch.float16, device='cuda')

        # launch configuration: 16×16 threads per block
        block = (16, 16, 1)
        grid = ((N + block[0] - 1) // block[0],
                (M + block[1] - 1) // block[1],
                1)

        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            N,
            K
        ]

        ptx_launch(self.module, "gemm_kernel", grid, block, args)
        return C
